-- 10 Grants: relation, column, routine, schema, default privileges. Excludes grants held by the object owner.
select jsonb_build_object(
'relation_grants',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'relation',c.relname,'kind',c.relkind,'grantee',case a.grantee when 0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privileges',a.privs) order by n.nspname,c.relname,case a.grantee when 0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end),'[]')
  from pg_class c join pg_namespace n on n.oid=c.relnamespace
  cross join lateral (select e.grantee, string_agg(e.privilege_type||case when e.is_grantable then '*' else '' end, ',' order by e.privilege_type) privs from aclexplode(c.relacl) e where e.grantee<>c.relowner group by e.grantee) a
  where n.nspname !~ '^pg_' and n.nspname !~ '^supabase_' and n.nspname not in ('information_schema','auth','storage','realtime','extensions','graphql','graphql_public','vault','pgsodium','pgsodium_masks','cron','pgbouncer','net','supabase_functions','_realtime','_analytics','pgtle','topology','tiger','tiger_data') and c.relkind in ('r','p','v','m','S','f')),
'column_grants',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'relation',c.relname,'column',at.attname,'grantee',case e.grantee when 0 then 'PUBLIC' else pg_get_userbyid(e.grantee) end,'privilege',e.privilege_type) order by n.nspname,c.relname,at.attname,e.grantee::regrole::text,e.privilege_type),'[]')
  from pg_attribute at join pg_class c on c.oid=at.attrelid join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(at.attacl) e
  where n.nspname !~ '^pg_' and n.nspname !~ '^supabase_' and n.nspname not in ('information_schema','auth','storage','realtime','extensions','graphql','graphql_public','vault','pgsodium','pgsodium_masks','cron','pgbouncer','net','supabase_functions','_realtime','_analytics','pgtle','topology','tiger','tiger_data') and at.attacl is not null and not at.attisdropped),
'routine_grants',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'routine',p.proname||'('||pg_get_function_identity_arguments(p.oid)||')','grantee',case a.grantee when 0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privileges',a.privs) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),case a.grantee when 0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end),'[]')
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  cross join lateral (select e.grantee, string_agg(e.privilege_type, ',' order by e.privilege_type) privs from aclexplode(coalesce(p.proacl, acldefault('f',p.proowner))) e where e.grantee<>p.proowner group by e.grantee) a
  where n.nspname !~ '^pg_' and n.nspname !~ '^supabase_' and n.nspname not in ('information_schema','auth','storage','realtime','extensions','graphql','graphql_public','vault','pgsodium','pgsodium_masks','cron','pgbouncer','net','supabase_functions','_realtime','_analytics','pgtle','topology','tiger','tiger_data') and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')),
'schema_grants',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'grantee',case e.grantee when 0 then 'PUBLIC' else pg_get_userbyid(e.grantee) end,'privilege',e.privilege_type) order by n.nspname,case e.grantee when 0 then 'PUBLIC' else pg_get_userbyid(e.grantee) end,e.privilege_type),'[]')
  from pg_namespace n cross join lateral aclexplode(n.nspacl) e where n.nspname !~ '^pg_' and n.nspname !~ '^supabase_' and n.nspname not in ('information_schema','auth','storage','realtime','extensions','graphql','graphql_public','vault','pgsodium','pgsodium_masks','cron','pgbouncer','net','supabase_functions','_realtime','_analytics','pgtle','topology','tiger','tiger_data') and e.grantee<>n.nspowner),
'default_privileges',(select coalesce(jsonb_agg(jsonb_build_object('for_role',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'object_type',d.defaclobjtype,'acl',d.defaclacl::text) order by pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype),'[]')
  from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace)
) as result;
